/* IIOD server session (libtinyiiod): the input is the byte stream a client sends to iiod, served
 * over an emulated fmcomms2 context. iiod_interpreter() is the same entry point iiod-emu uses for
 * every connection, and runs the shared iiod/responder.c command handlers. */
#include <errno.h>
#include <iio/iio.h>
#include <libxml/parser.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <tinyiiod.h>
#include <dirent.h>
#include <unistd.h>

/* fixture_xml[], fixture_xml_len, fixture_bin[], fixture_bin_len: generated by build.sh from
 * tests/resources/xmls. */
#include "fixtures.h"

#define FIXTURE_XML "fmcomms2.xml"
#define FIXTURE_BIN "cf-ad9361-lpc_buf0.bin"

struct iiod_pdata {
	const uint8_t *data;
	size_t size;
	size_t pos;
};

static ssize_t read_cb(struct iiod_pdata *pdata, void *buf, size_t len)
{
	size_t n = pdata->size - pdata->pos;

	if (!n)
		return -ECONNRESET;
	if (n > len)
		n = len;
	memcpy(buf, pdata->data + pdata->pos, n);
	pdata->pos += n;
	return n;
}

static ssize_t write_cb(struct iiod_pdata *pdata, const void *buf, size_t len)
{
	(void)pdata;
	(void)buf;
	return len;
}

static void quiet(void *ctx, const char *msg, ...)
{
	(void)ctx;
	(void)msg;
}

static char dir[4096];

static int write_file(const char *name, const void *data, size_t len)
{
	char path[4200];
	FILE *f;

	snprintf(path, sizeof(path), "%s/%s", dir, name);
	f = fopen(path, "wb");
	if (!f)
		return -1;
	fwrite(data, 1, len, f);
	return fclose(f);
}

int LLVMFuzzerInitialize(int *argc, char ***argv)
{
	const char *tmp = getenv("TMPDIR");

	(void)argc;
	(void)argv;
	xmlSetGenericErrorFunc(NULL, quiet);
	iiod_params.log_level = LEVEL_NOLOG;
	snprintf(dir, sizeof(dir), "%s/tinyiiod-XXXXXX", tmp && *tmp ? tmp : "/tmp");
	if (!mkdtemp(dir))
		return 1;
	/* The fixtures are written once and only read afterwards. */
	if (write_file(FIXTURE_XML, fixture_xml, fixture_xml_len) ||
			write_file(FIXTURE_BIN, fixture_bin, fixture_bin_len))
		return 1;
	return iiod_init();
}

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size)
{
	struct iio_context_params params = { .log_level = LEVEL_NOLOG };
	struct iiod_pdata pdata = { .data = data, .size = size };
	struct iio_context *ctx;
	char uri[4200], path[4200];
	DIR *d;

	snprintf(uri, sizeof(uri), "emu:%s/" FIXTURE_XML, dir);
	ctx = iio_create_context(&params, uri);
	if (!iio_err(ctx)) {
		(void)iiod_interpreter(ctx, &pdata, read_cb, write_cb, NULL, 0);
		iio_context_destroy(ctx);
	}

	/* Each input gets a fresh emulated context; the files it wrote (TX buffers) are removed. */
	d = opendir(dir);
	if (d) {
		struct dirent *e;

		while ((e = readdir(d))) {
			if (e->d_name[0] == '.' || !strcmp(e->d_name, FIXTURE_XML) ||
					!strcmp(e->d_name, FIXTURE_BIN))
				continue;
			snprintf(path, sizeof(path), "%s/%s", dir, e->d_name);
			unlink(path);
		}
		closedir(d);
	}
	return 0;
}
